export const SCHEMA_VERSION = MIGRATIONS.length

// Opens (and migrates) a database file; ':memory:' opens a private in-memory database (tests).
export function openDatabase(file: string): DatabaseSync {
  const memory = file === ':memory:'
  const path = memory ? file : resolve(file)
  if (!memory) mkdirSync(dirname(path), { recursive: true })
  const conn = new DatabaseSync(path)
  if (!memory) conn.exec('PRAGMA journal_mode = WAL;')
  conn.exec('PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 5000;')
  migrate(conn)
  return conn
}

function migrate(conn: DatabaseSync) {
  const { user_version: version } = conn.prepare('PRAGMA user_version').get() as { user_version: number }
  for (let v = version; v < MIGRATIONS.length; v++) {
    transaction(conn, () => {
      conn.exec(MIGRATIONS[v])
      conn.exec(`PRAGMA user_version = ${v + 1}`)
    })
  }
}

export function transaction<T>(conn: DatabaseSync, fn: () => T): T {
  conn.exec('BEGIN IMMEDIATE')
  try {
    const result = fn()
    conn.exec('COMMIT')
    return result
  } catch (err) {
    conn.exec('ROLLBACK')
    throw err
  }
}
